[
  {
    "id": "M1",
    "artifact_required": true,
    "goal": "地基与外壳跑起来：Vite+React+TS 工程可生产构建、可启动；数据模型（Scene / Item / Placement）+ LocalStorage 持久化就位；内置素材库枚举出 3 张背景 + 14 件物件；应用外壳（报头 + 模式开关 + 场景条 + 物件抽屉 + 画布）渲染，能创建/切换场景，刷新后状态还原。",
    "criteria": [
      {
        "desc": "生产构建通过：Vite 生产构建成功、无类型错误。",
        "check": {
          "type": "command",
          "cmd": [
            "npm",
            "run",
            "build"
          ],
          "expect_exit": 0,
          "timeout_ms": 180000
        }
      },
      {
        "desc": "外壳与持久化 e2e：建场景→切场景→刷新后场景与布局状态完整还原；物件抽屉列出 14 件；场景背景不可重复且最多 3 个（建到第 4 个被阻止）。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/m1-shell.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 120000
        }
      },
      {
        "desc": "外壳视觉还原「旧信」DNA：暖奶油纸底、衬线品牌/场景名、陶土红唯一强调、Workbench(报头+场景条+[抽屉|画布]) 布局，对齐 A-旧信.html 与 tokens.css。",
        "manual": true
      }
    ],
    "status": "done",
    "verdicts": [
      {
        "milestone": "M1",
        "pass": true,
        "failed": []
      }
    ]
  },
  {
    "id": "M2",
    "artifact_required": true,
    "goal": "核心变换交互顺滑：物件可从抽屉拖入画布，可拖动改位、角手柄缩放、顶部手柄旋转、移除；变换经 CSS transform；PC 与横屏手机统一用手柄；placement(x,y,scale,rotation,z) 持久化，刷新完整还原。",
    "criteria": [
      {
        "desc": "变换交互 e2e：物件从抽屉拖入→拖动改位→角手柄缩放→顶部手柄旋转→移除→刷新后 placement(x,y,scale,rotation,z) 完整还原。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/m2-transform.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 120000
        }
      },
      {
        "desc": "顺滑手感：拖/缩/转跟手、无肉眼可见掉帧或位置/角度跳变、手柄命中准；在 PC 与横屏手机各验一遍。",
        "manual": true
      },
      {
        "desc": "变换仅走 transform/opacity、不触发布局重排（合成层 + requestAnimationFrame 提交）。",
        "manual": true
      }
    ],
    "status": "done",
    "verdicts": [
      {
        "milestone": "M2",
        "pass": true,
        "failed": []
      }
    ]
  },
  {
    "id": "M3",
    "artifact_required": true,
    "goal": "物件故事与编辑/游客双模式：选中物件写/改故事（故事挂物件本身、跨场景同步）；点物件弹出半透明故事弹窗（含原始图片）；编辑↔游客一键切换；游客模式只读，点物件只弹故事+原图、不能编辑；故事持久化。",
    "criteria": [
      {
        "desc": "故事与双模式 e2e：选中物件写故事→刷新后还原→同一物件在另一场景故事同步更新→切游客模式点物件只弹故事+原图且不可编辑/移动。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/m3-story.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 120000
        }
      },
      {
        "desc": "故事弹窗视觉：半透明奶油底 + backdrop-blur 透出背后画布、陶土红衬线、含原始照片，浮于画布之上不占画布宽度，还原「旧信」DNA。",
        "manual": true
      }
    ],
    "status": "done",
    "verdicts": [
      {
        "milestone": "M3",
        "pass": true,
        "failed": []
      }
    ]
  },
  {
    "id": "M4",
    "artifact_required": true,
    "goal": "收口·全流程 + 双端达标：覆盖 6 条成功条件的端到端全流程在 PC 与横屏手机都跑通、布局不错乱；整体还原「旧信」DNA；无横向溢出、无未捕获运行时错误。",
    "criteria": [
      {
        "desc": "全流程 + 双端 e2e：覆盖 6 条成功条件主链路，在 PC / 768px / 375px 三视口跑通；无横向溢出；无 console 未捕获错误或未处理的 Promise 拒绝。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/m4-full.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 180000
        }
      },
      {
        "desc": "双端布局与整体视觉验收：横屏手机布局不错乱、元素不溢出遮挡；整体还原「旧信」DNA（配色/字体/间距/弹窗/手柄均走 tokens.css）。",
        "manual": true
      }
    ],
    "status": "done",
    "verdicts": [
      {
        "milestone": "M4",
        "pass": true,
        "failed": []
      }
    ]
  },
  {
    "id": "N1",
    "artifact_required": false,
    "goal": "素材与数据地基（回炉第一块）：14 张物件 PNG 经 alpha 阈值裁边（烘焙软阴影不算实体）、四边透明边 ≤8px、素材清单同步真实宽高比；新增横版书房场景图（横向构图、分辨率与客厅同量级）替换竖图为默认书房；存储 schema 升 v2——placement 坐标改为场景图坐标系百分比、旧像素数据作废不迁移（应用遇 v1 数据不崩、清空重摆）、Item.story 结构保留；工程可生产构建。",
    "criteria": [
      {
        "desc": "生产构建通过：Vite 生产构建成功、无类型错误。",
        "check": {
          "type": "command",
          "cmd": [
            "npm",
            "run",
            "build"
          ],
          "expect_exit": 0,
          "timeout_ms": 180000
        }
      },
      {
        "desc": "素材裁切达标：校验脚本逐张测 14 张物件 PNG，四边透明边 ≤8px、清单标注宽高比与实体一致（含新横版书房图存在且为横向）。",
        "check": {
          "type": "command",
          "cmd": [
            "node",
            "scripts/check-asset-trim.mjs"
          ],
          "expect_exit": 0,
          "timeout_ms": 60000
        }
      },
      {
        "desc": "schema v2 e2e：百分比坐标读写与刷新还原；预置 v1 旧数据启动不崩、按作废处理；故事字段结构保留。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/n1-foundation.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 120000
        }
      },
      {
        "desc": "横版书房图对味：暖调胶片质感与客厅/卧室成一组，还原「旧信」气质。",
        "manual": true
      }
    ],
    "claimed_at_tick": 14
  },
  {
    "id": "N2",
    "artifact_required": true,
    "goal": "满屏沉浸外壳与场景自适应层：场景铺满视口（无定宽留白、无元素堆角、无横向滚动）；任意比例场景 contain 居中＋同图模糊补边不截断；物件按百分比锚定（窗口任意缩放钉在房间同一相对位置）；毛玻璃浮层四件套（品牌章/模式开关＋隐藏界面钮/场景条/物件 dock）；dock 可收合且视觉居中；拖动时浮层整体让路；UI 标签字号 ≥11px。",
    "criteria": [
      {
        "desc": "外壳与自适应 e2e：1280/1920/2560 与横屏手机视口均无横向溢出、外壳铺满；缩放窗口后物件相对场景位置不变；竖图场景图面完整可见；拖动中浮层不接指针且物件可落点在浮层常驻区。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/n2-shell.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 180000
        }
      },
      {
        "desc": "沉浸观感验收：玻璃材质/让路动效/暗角与模糊补边对齐 A2-旧信-沉浸.html 与 design.md v2；dock 收合把手不挤偏内容。",
        "manual": true
      }
    ]
  },
  {
    "id": "N3",
    "artifact_required": true,
    "goal": "编辑交互与管理全量：Canva 式手柄（陶土红细选框＋四角白圆点缩放＋下方旋转圆钮＋浮动毛玻璃工具条·真 SVG 图标）；dock 拖出新物件、挪位/缩放/旋转/移除/写故事全链路；管理与命名——场景重命名与删除（删除释放背景配额可再建）、物件重命名（挂 Item 跨场景同步）、陈列室名就地编辑；全部持久化。",
    "criteria": [
      {
        "desc": "编辑与管理 e2e：dock 拖入→挪位→角手柄缩放→旋转钮旋转→工具条移除；场景重命名/删除后配额释放可再建；物件重命名跨场景同步；陈列室名就地编辑；以上刷新后全还原。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/n3-edit.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 180000
        }
      },
      {
        "desc": "手感验收：拖/缩/转在 PC 与横屏手机跟手、不掉帧、无跳变；手柄触摸可命中（≥ --h2-hit）；无字符图标残留。",
        "manual": true
      }
    ]
  },
  {
    "id": "N4",
    "artifact_required": true,
    "goal": "双模式、双端与收口：游客模式（浮层收到最简、点物件只读弹故事＋原图）；故事弹窗适配满屏与窄屏（贴底近满宽）；覆盖 9 条成功条件的端到端全流程在 PC 与横屏手机跑通；无 console 未捕获错误、无横向溢出；整体还原「旧信 · 沉浸」DNA。",
    "criteria": [
      {
        "desc": "全流程收口 e2e：覆盖 9 条成功条件主链路，在 PC（1920）与横屏手机（844×390）双视口跑通；无横向溢出；无 console 未捕获错误或未处理 Promise 拒绝。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/n4-full.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 240000
        }
      },
      {
        "desc": "终验：双端视觉不错乱；整体气质对尺 design.md v2 与 tokens.css v2（含工艺底线：字号下限、选框贴实物）。",
        "manual": true
      }
    ]
  }
]

